{"source": "def investigate(context, acquire):
    receipts = acquire("history")

    def run(actions, put_mode, instrument, channel_mode):
        state = {}
        txn = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last = {"main": 0, "other": 0}

        def apply(conn, key, value, is_update, is_delete):
            if is_delete:
                if key in state:
                    del state[key]
                    changed = 1
                else:
                    changed = 0
            elif is_update:
                if key in state:
                    state[key] = value
                    changed = 1
                else:
                    changed = 0
            else:
                if key in state:
                    if put_mode == "ignore":
                        changed = 0
                    else:
                        state[key] = value
                        changed = 1
                else:
                    state[key] = value
                    changed = 1
            if changed:
                total[conn] += changed
                last[conn] = changed
            else:
                last[conn] = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = []
            elif op == "commit":
                if txn[conn] is not None:
                    for (k, v, iu, idl) in txn[conn]:
                        apply(conn, k, v, iu, idl)
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                k = act.get("key")
                v = act.get("value", 0)
                iu = (op == "update")
                idl = (op == "delete")
                if txn[conn] is not None:
                    txn[conn].append((k, v, iu, idl))
                else:
                    apply(conn, k, v, iu, idl)

        if channel_mode == "changes":
            return last["main"]
        elif channel_mode == "total_main":
            return total["main"]
        else:
            return total["main"] + total["other"]

    def committed(actions, put_mode):
        st = {}
        txn = {"main": None, "other": None}
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = []
            elif op == "commit":
                if txn[conn] is not None:
                    for (k, v, iu, idl) in txn[conn]:
                        if idl:
                            if k in st:
                                del st[k]
                        elif iu:
                            if k in st:
                                st[k] = v
                        else:
                            if k in st:
                                if put_mode != "ignore":
                                    st[k] = v
                            else:
                                st[k] = v
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                k = act.get("key")
                v = act.get("value", 0)
                iu = (op == "update")
                idl = (op == "delete")
                if txn[conn] is not None:
                    txn[conn].append((k, v, iu, idl))
                else:
                    if idl:
                        if k in st:
                            del st[k]
                    elif iu:
                        if k in st:
                            st[k] = v
                    else:
                        if k in st:
                            if put_mode != "ignore":
                                st[k] = v
                        else:
                            st[k] = v
        return st

    put_modes = ["ignore", "replace", "upsert"]
    instruments = [False, True]
    channel_modes = ["changes", "total_main", "total_both"]

    consistent = []
    for pm in put_modes:
        for inst in instruments:
            for cm in channel_modes:
                ok = True
                for r in receipts:
                    acts = r.get("actions", [])
                    obs = r.get("observed", {})
                    if run(acts, pm, inst, cm) != obs.get("channel"):
                        ok = False
                        break
                    st = committed(acts, pm)
                    if len(st) != obs.get("committed_count"):
                        ok = False
                        break
                    if sum(st.values()) != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    consistent.append((pm, inst, cm))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for (pm, inst, cm) in consistent:
        if goal == "channel":
            results.append(run(actions, pm, inst, cm))
        else:
            st = committed(actions, pm)
            if goal == "committed_count":
                results.append(len(st))
            else:
                results.append(sum(st.values()))

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Enumerate the 18-member family, filter by calibration receipts, and predict only when all consistent members agree.", "lesson": "The channel is changes() on main, put is INSERT OR IGNORE, and there is no trigger; simulate all consistent candidates and require agreement."}
